</code></pre> bootstrap.php<pre><code>&lt;?php

define('BASE_PATH', __DIR__);
require __DIR__ . '/vendor/autoload.php';

use function Naf\app;

app()-&gt;run();
</code></pre> <p><code>naf/database</code> 0.2.4+ registers the configured connection under <code>PDO::class</code>, which the auth model factory uses. If an existing application locks an older version, update that dependency before using this bootstrap file.</p>

app/Models/User.php<pre><code>&lt;?php

namespace App\Models;

use Naf\Auth\Identity\{UserInterface, UserProfile};
use Naf\ORM\Model\AbstractModel;

final class User extends AbstractModel implements UserInterface
{
    protected string $username = '';
    protected string $password = '';
    protected string $roles = '';
    protected int $suspended = 0;
    protected string $name = '';
    protected string $email = '';
    protected int $email_verified = 0;

    public function getIdentifier(): string { return (string) $this-&gt;id; }
    public function getRoles(): iterable
    {
        return $this-&gt;roles === '' ? [] : explode(',', $this-&gt;roles);
    }
    public function getPermissions(): iterable { return []; }
    public function isActive(): bool { return $this-&gt;suspended === 0; }
    public function getProfile(): UserProfile
    {
        return new UserProfile($this-&gt;name, $this-&gt;email, $this-&gt;email_verified === 1);
    }
    public function getUsername(): string { return $this-&gt;username; }
    public function getPassword(): string { return $this-&gt;password; }
    public function setPassword(string $password): void { $this-&gt;password = $password; }
}
</code></pre> <p><code>UserInterface</code> extends <code>IdentityInterface</code>. <code>isActive()</code> rejects suspended accounts both at login and on restoration. <code>getProfile()</code> deliberately selects the fields an OAuth consent screen or UserInfo response may expose.</p>

